// Recebe o POST do bookmarklet aberto NA PAGINA da marca no Reclame AQUI (um navegador de
// verdade passa pelo anti-bot; curl e n8n tomam 403). Corpo: {marca, ra:{...}} em text/plain.
// A chave vai na query (?k=) e e validada NO SQL contra crm_dash_chave (painel cx ou todos, ativa):
// chave errada = nada gravado, sem erro (o bookmarklet nao le a resposta).
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
else if (body && typeof body === 'object' && !body.marca) {
  const ks = Object.keys(body);
  if (ks.length && ks[0].trim().startsWith('{')) { try { body = JSON.parse(ks[0] + (body[ks[0]] || '')); } catch (e) { body = {}; } }
}
const k = String(($json.query || {}).k || '').trim();
const MARCAS = ['aristocrata', 'fishermans', 'olivas'];
const marca = MARCAS.includes(body.marca) ? body.marca : null;
const ra = body.ra || {};
if (!marca || !k) return [{ json: { sql: 'SELECT 0 AS ignorado' } }];
const num = (v) => { if (v === null || v === undefined || v === '') return 'NULL'; const n = Number(String(v).replace(',', '.')); return Number.isNaN(n) ? 'NULL' : String(n); };
const txt = (v) => v === null || v === undefined ? 'NULL' : "'" + String(v).slice(0, 40).replace(/'/g, "''") + "'";
const vals = [ "'" + marca + "'", num(ra.nota), num(ra.resposta_pct), num(ra.solucao_pct), num(ra.voltaria_pct), num(ra.nota_consumidor),
  num(ra.reclamacoes), num(ra.avaliacoes), num(ra.aguardando), num(ra.tempo_resposta_dias), txt(ra.status_ra), "'bookmarklet'" ].join(',');
return [{ json: { sql: `INSERT INTO cx_ra_dia (marca, nota, resposta_pct, solucao_pct, voltaria_pct, nota_consumidor, reclamacoes, avaliacoes, aguardando, tempo_resposta_dias, status_ra, fonte, dia)
  SELECT v.marca, v.nota::numeric, v.resposta_pct::numeric, v.solucao_pct::numeric, v.voltaria_pct::numeric, v.nota_consumidor::numeric,
         v.reclamacoes::int, v.avaliacoes::int, v.aguardando::int, v.tempo_resposta_dias::numeric, v.status_ra::text, v.fonte::text, (now() AT TIME ZONE 'America/Sao_Paulo')::date
  FROM (VALUES (${vals})) AS v(marca, nota, resposta_pct, solucao_pct, voltaria_pct, nota_consumidor, reclamacoes, avaliacoes, aguardando, tempo_resposta_dias, status_ra, fonte)
  WHERE EXISTS (SELECT 1 FROM crm_dash_chave WHERE chave = ${"'" + k.replace(/'/g, "''") + "'"} AND ativo AND painel IN ('cx','todos'))
  ON CONFLICT (marca, dia) DO UPDATE SET nota=EXCLUDED.nota, resposta_pct=EXCLUDED.resposta_pct, solucao_pct=EXCLUDED.solucao_pct,
    voltaria_pct=EXCLUDED.voltaria_pct, nota_consumidor=EXCLUDED.nota_consumidor, reclamacoes=EXCLUDED.reclamacoes, avaliacoes=EXCLUDED.avaliacoes,
    aguardando=EXCLUDED.aguardando, tempo_resposta_dias=EXCLUDED.tempo_resposta_dias, status_ra=EXCLUDED.status_ra, fonte=EXCLUDED.fonte, coletado_em=now()` } }];
